1	import type { EditorAction, EditorState } from "./types";
2	import { createInitialState } from "./types";
3	
4	export function editorReducer(state: EditorState, action: EditorAction): EditorState {
5	  switch (action.type) {
6	    case "INIT_MEMO":
7	      return {
8	        ...state,
9	        content: action.payload.content,
10	        metadata: action.payload.metadata,
11	        timestamps: action.payload.timestamps,
12	      };
13	
14	    case "UPDATE_CONTENT":
15	      return {
16	        ...state,
17	        content: action.payload,
18	      };
19	
20	    case "SET_METADATA":
21	      return {
22	        ...state,
23	        metadata: {
24	          ...state.metadata,
25	          ...action.payload,
26	        },
27	      };
28	
29	    case "ADD_LOCAL_FILE":
30	      return {
31	        ...state,
32	        localFiles: [...state.localFiles, action.payload],
33	      };
34	
35	    case "REMOVE_LOCAL_FILE":
36	      return {
37	        ...state,
38	        localFiles: state.localFiles.filter((f) => f.previewUrl !== action.payload),
39	      };
40	
41	    case "SET_LOCAL_FILES":
42	      return {
43	        ...state,
44	        localFiles: action.payload,
45	      };
46	
47	    case "TOGGLE_FOCUS_MODE":
48	      return {
49	        ...state,
50	        ui: {
51	          ...state.ui,
52	          isFocusMode: !state.ui.isFocusMode,
53	        },
54	      };
55	
56	    case "SET_LOADING":
57	      return {
58	        ...state,
59	        ui: {
60	          ...state.ui,
61	          isLoading: {
62	            ...state.ui.isLoading,
63	            [action.payload.key]: action.payload.value,
64	          },
65	        },
66	      };
67	
68	    case "SET_TIMESTAMPS":
69	      return {
70	        ...state,
71	        timestamps: {
72	          ...state.timestamps,
73	          ...action.payload,
74	        },
75	      };
76	
77	    case "SET_RECORDER_BUSY":
78	      return {
79	        ...state,
80	        recorderBusy: action.payload,
81	      };
82	
83	    case "RESET":
84	      return createInitialState();
85	
86	    default:
87	      return state;
88	  }
89	}
