1	import type { Attachment } from "@/types/proto/api/v1/attachment_service_pb";
2	import type { Location, MemoRelation } from "@/types/proto/api/v1/memo_service_pb";
3	import { Visibility } from "@/types/proto/api/v1/memo_service_pb";
4	import type { LocalFile } from "../types/attachment";
5	
6	export type LoadingKey = "saving" | "uploading" | "loading";
7	
8	export interface EditorState {
9	  content: string;
10	  metadata: {
11	    visibility: Visibility;
12	    attachments: Attachment[];
13	    relations: MemoRelation[];
14	    location?: Location;
15	  };
16	  ui: {
17	    isFocusMode: boolean;
18	    isLoading: {
19	      saving: boolean;
20	      uploading: boolean;
21	      loading: boolean;
22	    };
23	  };
24	  timestamps: {
25	    createTime?: Date;
26	    updateTime?: Date;
27	  };
28	  localFiles: LocalFile[];
29	  /** Whether an audio recording is in flight; gates save. The recorder's full
30	   *  state lives in useAudioRecorder — only this shared bit reaches the store. */
31	  recorderBusy: boolean;
32	}
33	
34	export type EditorAction =
35	  | { type: "INIT_MEMO"; payload: { content: string; metadata: EditorState["metadata"]; timestamps: EditorState["timestamps"] } }
36	  | { type: "UPDATE_CONTENT"; payload: string }
37	  | { type: "SET_METADATA"; payload: Partial<EditorState["metadata"]> }
38	  | { type: "ADD_LOCAL_FILE"; payload: LocalFile }
39	  | { type: "REMOVE_LOCAL_FILE"; payload: string }
40	  | { type: "SET_LOCAL_FILES"; payload: LocalFile[] }
41	  | { type: "TOGGLE_FOCUS_MODE" }
42	  | { type: "SET_LOADING"; payload: { key: LoadingKey; value: boolean } }
43	  | { type: "SET_TIMESTAMPS"; payload: Partial<EditorState["timestamps"]> }
44	  | { type: "SET_RECORDER_BUSY"; payload: boolean }
45	  | { type: "RESET" };
46	
47	// Module-private template for createInitialState.
48	const defaultState: EditorState = {
49	  content: "",
50	  metadata: {
51	    visibility: Visibility.PRIVATE,
52	    attachments: [],
53	    relations: [],
54	    location: undefined,
55	  },
56	  ui: {
57	    isFocusMode: false,
58	    isLoading: {
59	      saving: false,
60	      uploading: false,
61	      loading: false,
62	    },
63	  },
64	  timestamps: {
65	    createTime: undefined,
66	    updateTime: undefined,
67	  },
68	  localFiles: [],
69	  recorderBusy: false,
70	};
71	
72	/** Fresh initial state for a mounting editor. */
73	export function createInitialState(): EditorState {
74	  return {
75	    ...defaultState,
76	    ui: { ...defaultState.ui },
77	  };
78	}
